#!/usr/bin/env node
/**
 * Package a skill folder into a distributable .skill file (ZIP archive).
 *
 * Usage:
 *   node package_skill.cjs [skill-folder] [output-dir]
 *
 * - skill-folder (optional): default is this script's own directory.
 * - output-dir (optional): default is the skill folder's parent directory.
 *
 * Validation performed before packaging:
 *   - SKILL.md exists with YAML frontmatter containing `name` and `description`
 *   - frontmatter contains no fields other than name/description
 *   - `name` matches the skill folder name
 *   - description is non-trivial (>= 20 chars)
 *   - no TODO placeholders remain in SKILL.md, references/, or scripts/
 *   - every file referenced from SKILL.md exists
 *
 * Output is LLM-friendly: "Success: ..." or "Error: ..." — never a traceback.
 */
'use strict';

const fs = require('fs');
const path = require('path');

// ---------- CRC32 ----------
const CRC_TABLE = (() => {
  const t = new Uint32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    t[n] = c >>> 0;
  }
  return t;
})();

function crc32(buf) {
  let c = 0xffffffff;
  for (let i = 0; i < buf.length; i++) c = CRC_TABLE[(c ^ buf[i]) & 0xff] ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
}

function dosDateTime(date) {
  const time = (date.getHours() << 11) | (date.getMinutes() << 5) | (date.getSeconds() >> 1);
  const d = ((date.getFullYear() - 1980) << 9) | ((date.getMonth() + 1) << 5) | date.getDate();
  return { time: time & 0xffff, date: d & 0xffff };
}

// ---------- Skill collection & validation ----------
function collectFiles(dir, excludeNames) {
  const out = [];
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    if (excludeNames.has(entry.name)) continue;
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) out.push(...collectFiles(full, excludeNames));
    else out.push(full);
  }
  return out;
}

function parseFrontmatter(text) {
  if (!text.startsWith('---\n')) return null;
  const end = text.indexOf('\n---\n', 4);
  if (end < 0) return null;
  const fields = {};
  for (const line of text.slice(4, end).split('\n')) {
    const m = line.match(/^([A-Za-z0-9_-]+):\s*(.*)$/);
    if (m) fields[m[1]] = m[2];
  }
  return fields;
}

function validate(skillDir, errors) {
  const skillName = path.basename(skillDir);
  const skillMdPath = path.join(skillDir, 'SKILL.md');
  if (!fs.existsSync(skillMdPath)) {
    errors.push('SKILL.md is missing');
    return;
  }
  const skillMd = fs.readFileSync(skillMdPath, 'utf8');
  const fm = parseFrontmatter(skillMd);
  if (!fm) {
    errors.push('SKILL.md must start with YAML frontmatter (---\\nname: ...\\ndescription: ...\\n---)');
    return;
  }
  const extra = Object.keys(fm).filter((k) => k !== 'name' && k !== 'description');
  if (extra.length) errors.push('frontmatter contains unexpected fields: ' + extra.join(', '));
  if (!fm.name) errors.push('frontmatter is missing `name`');
  else if (fm.name !== skillName) errors.push('frontmatter `name` (' + fm.name + ') does not match folder name (' + skillName + ')');
  if (!fm.description) errors.push('frontmatter is missing `description`');
  else if (fm.description.trim().length < 20) errors.push('`description` is too short to be useful');
  if (/TODO/i.test(skillMd)) errors.push('TODO placeholder remains in SKILL.md');

  // Every markdown link target referenced from SKILL.md must exist.
  const refs = [...skillMd.matchAll(/\]\(([^)#]+)\)/g)].map((m) => m[1]);
  for (const ref of refs) {
    if (!fs.existsSync(path.join(skillDir, ref))) errors.push('SKILL.md references missing file: ' + ref);
  }

  // TODO scan over bundled resources (skip the packaging script itself).
  const excludeNames = new Set([path.basename(__filename)]);
  for (const file of collectFiles(skillDir, excludeNames)) {
    const text = fs.readFileSync(file, 'utf8');
    if (/TODO/i.test(text)) errors.push('TODO placeholder remains in ' + path.relative(skillDir, file));
  }
}

// ---------- ZIP writer (store, no compression) ----------
function buildZip(entries) {
  const chunks = [];
  let offset = 0;
  for (const e of entries) {
    const lfh = Buffer.alloc(30);
    lfh.writeUInt32LE(0x04034b50, 0); // local file header signature
    lfh.writeUInt16LE(20, 4); // version needed
    lfh.writeUInt16LE(0x0800, 6); // flags: UTF-8 names
    lfh.writeUInt16LE(0, 8); // method: store
    lfh.writeUInt16LE(e.time, 10);
    lfh.writeUInt16LE(e.date, 12);
    lfh.writeUInt32LE(e.crc, 14);
    lfh.writeUInt32LE(e.data.length, 18); // compressed size
    lfh.writeUInt32LE(e.data.length, 22); // uncompressed size
    lfh.writeUInt16LE(e.nameBuf.length, 26);
    lfh.writeUInt16LE(0, 28); // extra length
    chunks.push(lfh, e.nameBuf, e.data);
    e.localOffset = offset;
    offset += 30 + e.nameBuf.length + e.data.length;
  }
  const cdStart = offset;
  const cdChunks = [];
  for (const e of entries) {
    const cd = Buffer.alloc(46);
    cd.writeUInt32LE(0x02014b50, 0); // central directory signature
    cd.writeUInt16LE(20, 4); // version made by
    cd.writeUInt16LE(20, 6); // version needed
    cd.writeUInt16LE(0x0800, 8); // flags
    cd.writeUInt16LE(0, 10); // method
    cd.writeUInt16LE(e.time, 12);
    cd.writeUInt16LE(e.date, 14);
    cd.writeUInt32LE(e.crc, 16);
    cd.writeUInt32LE(e.data.length, 20);
    cd.writeUInt32LE(e.data.length, 24);
    cd.writeUInt16LE(e.nameBuf.length, 28);
    cd.writeUInt16LE(0, 30); // extra length
    cd.writeUInt16LE(0, 32); // comment length
    cd.writeUInt16LE(0, 34); // disk number
    cd.writeUInt16LE(0, 36); // internal attrs
    cd.writeUInt32LE(0, 38); // external attrs
    cd.writeUInt32LE(e.localOffset, 42);
    cdChunks.push(cd, e.nameBuf);
    offset += 46 + e.nameBuf.length;
  }
  const cdSize = offset - cdStart;
  const eocd = Buffer.alloc(22);
  eocd.writeUInt32LE(0x06054b50, 0); // end of central directory signature
  eocd.writeUInt16LE(0, 4); // disk number
  eocd.writeUInt16LE(0, 6); // cd start disk
  eocd.writeUInt16LE(entries.length, 8);
  eocd.writeUInt16LE(entries.length, 10);
  eocd.writeUInt32LE(cdSize, 12);
  eocd.writeUInt32LE(cdStart, 16);
  eocd.writeUInt16LE(0, 20); // comment length
  return Buffer.concat([...chunks, ...cdChunks, eocd]);
}

function verifyZip(buf, expectedEntries) {
  if (buf.readUInt32LE(0) !== 0x04034b50) return false;
  if (buf.readUInt32LE(buf.length - 22) !== 0x06054b50) return false;
  return buf.readUInt16LE(buf.length - 12) === expectedEntries; // total entries in EOCD
}

// ---------- Main ----------
async function main() {
  const argv = process.argv.slice(2);
  const skillDir = path.resolve(argv[0] || __dirname);
  const outDir = path.resolve(argv[1] || path.dirname(skillDir));
  const skillName = path.basename(skillDir);

  const errors = [];
  validate(skillDir, errors);
  if (errors.length) {
    console.error('Error: skill validation failed:\n- ' + errors.join('\n- '));
    process.exit(1);
  }

  const excludeNames = new Set([path.basename(__filename)]);
  const files = collectFiles(skillDir, excludeNames).filter((f) => !f.endsWith('.skill'));
  const entries = files.map((file) => {
    const data = fs.readFileSync(file);
    const rel = path.relative(skillDir, file).split(path.sep).join('/');
    const nameBuf = Buffer.from(rel, 'utf8');
    const { time, date } = dosDateTime(fs.statSync(file).mtime);
    return { data, nameBuf, crc: crc32(data), time, date, localOffset: 0 };
  });

  const zip = buildZip(entries);
  if (!verifyZip(zip, entries.length)) {
    console.error('Error: internal zip verification failed; package not written.');
    process.exit(1);
  }

  fs.mkdirSync(outDir, { recursive: true });
  const outFile = path.join(outDir, skillName + '.skill');
  fs.writeFileSync(outFile, zip);

  console.log('Success: packaged ' + entries.length + ' file(s) into ' + outFile + ' (' + zip.length + ' bytes):');
  for (const e of entries) console.log('  - ' + e.nameBuf.toString('utf8'));
  process.exit(0);
}

module.exports = { crc32, buildZip, validate, collectFiles };

if (require.main === module) {
  main().catch((err) => {
    console.error('Error: ' + (err && err.message ? err.message : String(err)));
    process.exit(2);
  });
}

