#!/usr/bin/env node
/**
 * Slack Web API helper.
 *
 * Usage:
 *   node slack_request.cjs <api-method> [json-body] [options]
 *
 * Options:
 *   --token TOKEN      Slack token (defaults to $SLACK_TOKEN or $SLACK_BOT_TOKEN)
 *   --paginate         Follow response_metadata.next_cursor until exhausted
 *   --max-pages N      Cap number of pages when paginating (default 20)
 *   --max-retries N    Retries when Slack returns HTTP 429 (default 3)
 *   --base-url URL     Override base URL (mainly for testing/proxies)
 *   --help             Show this help and exit
 *
 * Examples:
 *   node slack_request.cjs api.test
 *   node slack_request.cjs conversations.list --paginate
 *   node slack_request.cjs chat.postMessage '{"channel":"#general","text":"hi"}'
 *
 * Output is LLM-friendly: "Success: ..." or "Error: ..." — never a traceback.
 */
'use strict';

const https = require('https');
const http = require('http');

const DEFAULT_BASE_URL = 'https://slack.com/api/';
const MAX_OUTPUT_CHARS = 4000;

function usage() {
  return [
    'Usage: node slack_request.cjs <api-method> [json-body] [options]',
    '',
    'Options:',
    '  --token TOKEN      Slack token (defaults to $SLACK_TOKEN or $SLACK_BOT_TOKEN)',
    '  --paginate         Follow response_metadata.next_cursor until exhausted',
    '  --max-pages N      Cap number of pages when paginating (default 20)',
    '  --max-retries N    Retries on HTTP 429 (default 3)',
    '  --base-url URL     Override base URL (mainly for testing/proxies)',
    '  --help             Show this help and exit',
    '',
    'Examples:',
    '  node slack_request.cjs api.test',
    '  node slack_request.cjs conversations.list --paginate',
    '  node slack_request.cjs chat.postMessage \'{"channel":"#general","text":"hi"}\'',
  ].join('\n');
}

function parseArgs(argv) {
  const args = {
    method: null,
    body: null,
    token: null,
    paginate: false,
    maxPages: 20,
    maxRetries: 3,
    baseUrl: DEFAULT_BASE_URL,
    help: false,
  };
  const positionals = [];
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === '--help' || a === '-h') {
      args.help = true;
    } else if (a === '--paginate') {
      args.paginate = true;
    } else if (a === '--token') {
      args.token = argv[++i];
    } else if (a === '--max-pages') {
      args.maxPages = parseInt(argv[++i], 10) || 20;
    } else if (a === '--max-retries') {
      args.maxRetries = parseInt(argv[++i], 10) || 3;
    } else if (a === '--base-url') {
      args.baseUrl = argv[++i];
    } else {
      positionals.push(a);
    }
  }
  args.method = positionals[0] || null;
  args.body = positionals[1] != null ? positionals[1] : null;
  return args;
}

function sleep(ms) {
  return new Promise(function (resolve) {
    setTimeout(resolve, ms);
  });
}

function requestOnce(baseUrl, apiMethod, opts) {
  return new Promise(function (resolve, reject) {
    const url = new URL(apiMethod, baseUrl.endsWith('/') ? baseUrl : baseUrl + '/');
    if (opts.cursor) {
      url.searchParams.set('cursor', opts.cursor);
    }
    const isPost = !!opts.body;
    const lib = url.protocol === 'https:' ? https : http;
    const headers = { 'Content-Type': 'application/json' };
    if (opts.token) {
      headers.Authorization = 'Bearer ' + opts.token;
    }
    const req = lib.request(url, { method: isPost ? 'POST' : 'GET', headers: headers }, function (res) {
      let data = '';
      res.setEncoding('utf8');
      res.on('data', function (chunk) {
        data += chunk;
      });
      res.on('end', function () {
        resolve({ status: res.statusCode, headers: res.headers, text: data });
      });
    });
    req.on('error', reject);
    if (isPost) {
      req.write(opts.body);
    }
    req.end();
  });
}

function mergePages(results) {
  const merged = {};
  for (const page of results) {
    for (const key of Object.keys(page)) {
      if (Array.isArray(page[key])) {
        merged[key] = (merged[key] || []).concat(page[key]);
      } else if (!(key in merged)) {
        merged[key] = page[key];
      }
    }
  }
  return merged;
}

async function callSlack(opts) {
  const baseUrl = opts.baseUrl || DEFAULT_BASE_URL;
  const apiMethod = opts.apiMethod;
  const maxRetries = opts.maxRetries != null ? opts.maxRetries : 3;
  const pages = [];
  let cursor = null;
  let pageCount = 0;
  let lastStatus = null;

  while (true) {
    pageCount++;
    let result = null;
    let attempt = 0;
    while (true) {
      result = await requestOnce(baseUrl, apiMethod, { token: opts.token, body: opts.body, cursor: cursor });
      attempt++;
      if (result.status === 429 && attempt <= maxRetries) {
        const retryAfter = parseFloat(result.headers['retry-after'] || '1');
        await sleep(Math.min(retryAfter, 60) * 1000);
        continue;
      }
      break;
    }
    lastStatus = result.status;
    let parsed = null;
    try {
      parsed = JSON.parse(result.text);
    } catch (e) {
      return { ok: false, error: 'invalid_json_response', status: result.status, raw: result.text.slice(0, 500) };
    }
    if (parsed && parsed.ok === false) {
      return { ok: false, error: parsed.error || 'unknown_error', status: result.status, parsed: parsed };
    }
    pages.push(parsed || {});
    if (!opts.paginate || pageCount >= (opts.maxPages || 20)) {
      break;
    }
    const next = parsed && parsed.response_metadata && parsed.response_metadata.next_cursor;
    if (!next) {
      break;
    }
    cursor = next;
  }

  const data = pages.length === 1 ? pages[0] : mergePages(pages);
  return { ok: true, status: lastStatus, pages: pages.length, data: data };
}

function summarize(method, outcome) {
  if (!outcome.ok) {
    let msg = 'Error: ' + method + ' -> ' + outcome.error;
    if (outcome.status) {
      msg += ' (HTTP ' + outcome.status + ')';
    }
    if (outcome.parsed && outcome.parsed.response_metadata && outcome.parsed.response_metadata.messages) {
      msg += ' | ' + outcome.parsed.response_metadata.messages.join('; ');
    }
    return msg;
  }
  let json = JSON.stringify(outcome.data);
  let prefix = 'Success: ' + method + ' (page(s): ' + outcome.pages + '): ';
  if (json.length > MAX_OUTPUT_CHARS) {
    json = json.slice(0, MAX_OUTPUT_CHARS) + ' ... [truncated]';
  }
  return prefix + json;
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  if (args.help) {
    console.log(usage());
    process.exit(0);
  }
  if (!args.method) {
    console.error(usage());
    process.exit(1);
  }
  if (!args.token) {
    args.token = process.env.SLACK_TOKEN || process.env.SLACK_BOT_TOKEN;
  }
  if (!args.token) {
    console.error('Error: no Slack token. Set SLACK_TOKEN (or SLACK_BOT_TOKEN), or pass --token.');
    process.exit(1);
  }
  if (args.body != null) {
    try {
      JSON.parse(args.body);
    } catch (e) {
      console.error('Error: body must be valid JSON.');
      process.exit(1);
    }
  }
  const outcome = await callSlack({
    apiMethod: args.method,
    body: args.body,
    token: args.token,
    paginate: args.paginate,
    maxPages: args.maxPages,
    maxRetries: args.maxRetries,
    baseUrl: args.baseUrl,
  });
  console.log(summarize(args.method, outcome));
  process.exit(outcome.ok ? 0 : 1);
}

module.exports = { parseArgs, requestOnce, callSlack, summarize, usage };

if (require.main === module) {
  main().catch(function (err) {
    console.error('Error: ' + (err && err.message ? err.message : String(err)));
    process.exit(2);
  });
}

#!/usr/bin/env node
/**
 * Offline test harness for slack-api/scripts/slack_request.cjs.
 * Spins up a local mock of the Slack Web API and exercises:
 *   - cursor pagination + page merging
 *   - HTTP 429 retry honoring Retry-After
 *   - ok:false error envelope + summarize output
 *   - non-JSON responses
 *   - argument parsing
 * Prints "Success: N checks passed" or "Error: ..." — never a traceback.
 */
'use strict';

const http = require('http');
const { parseArgs, callSlack, summarize } = require('./slack-api/scripts/slack_request.cjs');

const rateCount = { n: 0 };
const server = http.createServer((req, res) => {
  const url = new URL(req.url, 'http://localhost');
  const method = url.pathname.replace(/^\//, '');
  let body = '';
  req.on('data', (c) => { body += c; });
  req.on('end', () => {
    res.setHeader('content-type', 'application/json');
    if (method === 'conversations.list') {
      const cursor = url.searchParams.get('cursor') || '';
      if (cursor === '') {
        res.end(JSON.stringify({ ok: true, channels: [{ id: 'C1', name: 'general' }], response_metadata: { next_cursor: 'p2' } }));
      } else if (cursor === 'p2') {
        res.end(JSON.stringify({ ok: true, channels: [{ id: 'C2', name: 'random' }], response_metadata: { next_cursor: '' } }));
      } else {
        res.end(JSON.stringify({ ok: false, error: 'invalid_cursor' }));
      }
    } else if (method === 'rate.limited') {
      rateCount.n++;
      if (rateCount.n <= 2) {
        res.statusCode = 429;
        res.setHeader('retry-after', '0');
        res.end('rate limited');
      } else {
        res.end(JSON.stringify({ ok: true, note: 'recovered' }));
      }
    } else if (method === 'chat.postMessage') {
      let parsed = {};
      try { parsed = JSON.parse(body); } catch (e) { /* ignore */ }
      if (!parsed.text) {
        res.end(JSON.stringify({ ok: false, error: 'invalid_arguments', response_metadata: { messages: ['text is required'] } }));
      } else {
        res.end(JSON.stringify({ ok: true, ts: '1234.5678', channel: parsed.channel }));
      }
    } else if (method === 'bad.json') {
      res.end('<html>not json</html>');
    } else {
      res.end(JSON.stringify({ ok: false, error: 'method_not_found' }));
    }
  });
});

async function main() {
  await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
  const baseUrl = 'http://127.0.0.1:' + server.address().port + '/';
  const tok = 'xoxb-test';
  let passed = 0;
  const check = (name, cond, extra) => {
    if (!cond) throw new Error(name + ' failed' + (extra ? ': ' + extra : ''));
    passed++;
    console.log('  ok - ' + name);
  };

  const p = await callSlack({ apiMethod: 'conversations.list', token: tok, paginate: true, maxPages: 5, maxRetries: 1, baseUrl });
  check('pagination ok flag', p.ok === true, JSON.stringify(p));
  check('pagination merged channels', Array.isArray(p.data.channels) && p.data.channels.length === 2);
  check('pagination page count', p.pages === 2);
  check('success summary', summarize('conversations.list', p).startsWith('Success: conversations.list'));

  const r = await callSlack({ apiMethod: 'rate.limited', token: tok, maxRetries: 2, baseUrl });
  check('429 retry recovers', r.ok === true && r.data.note === 'recovered', JSON.stringify(r));

  const e = await callSlack({ apiMethod: 'chat.postMessage', token: tok, body: '{"channel":"C1"}', maxRetries: 1, baseUrl });
  check('error envelope surfaced', e.ok === false && e.error === 'invalid_arguments', JSON.stringify(e));
  check('error details in summary', summarize('chat.postMessage', e).includes('text is required'));

  const b = await callSlack({ apiMethod: 'bad.json', token: tok, maxRetries: 1, baseUrl });
  check('non-JSON response handled', b.ok === false && b.error === 'invalid_json_response', JSON.stringify(b));

  const a = parseArgs(['chat.postMessage', '{"text":"hi"}', '--paginate', '--max-pages', '7', '--token', 'xoxb-x']);
  check('parseArgs method', a.method === 'chat.postMessage');
  check('parseArgs body', a.body === '{"text":"hi"}');
  check('parseArgs options', a.paginate === true && a.maxPages === 7 && a.token === 'xoxb-x');

  server.close();
  console.log('Success: all ' + passed + ' checks passed');
}

main().catch((err) => {
  console.error('Error: ' + (err && err.message ? err.message : String(err)));
  server.close();
  process.exit(1);
});
